import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type AspectRatio = '1:1' | '3:4' | '4:3' | '9:16' | '16:9';
export type ImageSize = '1K' | '2K' | '4K';
export type ModelType = 'gemini-2.5-flash-image' | 'gemini-3-pro-image-preview';

export interface GeneratedImage {
  id: string;
  url: string;
  prompt: string;
  model: ModelType;
  timestamp: number;
  aspectRatio: AspectRatio;
  textOutput?: string;
}

export interface GenerationSettings {
  prompt: string;
  negativePrompt?: string;
  aspectRatio: AspectRatio;
  imageSize: ImageSize;
  model: ModelType;
}

declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

import { GoogleGenAI } from "@google/genai";
import { GenerationSettings, ModelType } from "../types";

export const generateImage = async (settings: GenerationSettings): Promise<{ imageUrl: string; text?: string }> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key is missing from environment.");

  const ai = new GoogleGenAI({ apiKey });

  const config: any = {
    imageConfig: {
      aspectRatio: settings.aspectRatio,
    }
  };

  // Only Pro model supports imageSize
  if (settings.model === 'gemini-3-pro-image-preview') {
    config.imageConfig.imageSize = settings.imageSize;
  }

  const response = await ai.models.generateContent({
    model: settings.model,
    contents: {
      parts: [
        { text: settings.prompt }
      ],
    },
    config,
  });

  let imageUrl = "";
  let text = "";

  if (response.candidates && response.candidates[0].content.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      } else if (part.text) {
        text += part.text;
      }
    }
  }

  if (!imageUrl) {
    throw new Error("No image data was returned by the model.");
  }

  return { imageUrl, text };
};

import React, { useState, useEffect, useCallback } from 'react';
import { 
  AspectRatio, 
  ImageSize, 
  ModelType, 
  GeneratedImage, 
  GenerationSettings 
} from './types';
import { generateImage } from './services/gemini';
import Sidebar from './components/Sidebar';
import Gallery from './components/Gallery';
import { Header } from './components/Header';

const App: React.FC = () => {
  const [images, setImages] = useState<GeneratedImage[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showKeyModal, setShowKeyModal] = useState(false);

  const [settings, setSettings] = useState<GenerationSettings>({
    prompt: '',
    aspectRatio: '1:1',
    imageSize: '1K',
    model: 'gemini-2.5-flash-image',
  });

  const handleGenerate = async () => {
    if (!settings.prompt.trim()) {
      setError("Please enter a prompt first.");
      return;
    }

    // Check for API key selection for Pro model
    if (settings.model === 'gemini-3-pro-image-preview') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        setShowKeyModal(true);
        return;
      }
    }

    setIsGenerating(true);
    setError(null);

    try {
      const result = await generateImage(settings);
      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: result.imageUrl,
        prompt: settings.prompt,
        model: settings.model,
        timestamp: Date.now(),
        aspectRatio: settings.aspectRatio,
        textOutput: result.text,
      };
      setImages(prev => [newImage, ...prev]);
    } catch (err: any) {
      console.error(err);
      if (err.message?.includes("Requested entity was not found")) {
        setError("API Session expired or invalid. Please re-select your API key.");
        if (settings.model === 'gemini-3-pro-image-preview') {
          setShowKeyModal(true);
        }
      } else {
        setError(err.message || "An unexpected error occurred during generation.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeySelect = async () => {
    try {
      await window.aistudio.openSelectKey();
      setShowKeyModal(false);
      // Proceed immediately as per instructions
      handleGenerate();
    } catch (err) {
      console.error("Failed to select key", err);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#0a0a0a]">
      <Header />

      <main className="flex flex-1 overflow-hidden relative">
        <Sidebar 
          settings={settings} 
          setSettings={setSettings} 
          onGenerate={handleGenerate} 
          isGenerating={isGenerating}
        />

        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-zinc-950/50">
          {error && (
            <div className="mb-6 p-4 bg-red-500/10 border border-red-500/50 rounded-xl text-red-500 flex items-center gap-3">
              <span className="text-xl">⚠️</span>
              <p>{error}</p>
              <button 
                onClick={() => setError(null)}
                className="ml-auto text-red-400 hover:text-red-300"
              >
                ✕
              </button>
            </div>
          )}

          <Gallery images={images} isGenerating={isGenerating} />
        </div>
      </main>

      {/* API Key Modal */}
      {showKeyModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-3xl max-w-md w-full shadow-2xl">
            <h2 className="text-2xl font-bold mb-4 banana-text-gradient">API Key Required</h2>
            <p className="text-zinc-400 mb-6 leading-relaxed">
              To use the <span className="text-white font-medium">Gemini 3 Pro</span> high-quality model, you must select your own API key from a paid GCP project.
            </p>
            <div className="flex flex-col gap-4">
              <button
                onClick={handleKeySelect}
                className="w-full py-4 rounded-xl banana-gradient text-black font-bold text-lg hover:scale-[1.02] transition-transform active:scale-95"
              >
                Select API Key
              </button>
              <a 
                href="https://ai.google.dev/gemini-api/docs/billing" 
                target="_blank" 
                rel="noopener noreferrer"
                className="text-center text-zinc-500 text-sm hover:underline"
              >
                Learn about Gemini API billing
              </a>
              <button
                onClick={() => setShowKeyModal(false)}
                className="text-zinc-500 hover:text-white transition-colors py-2"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

