import { GoogleGenAI } from "@google/genai";
import { GenerationSettings } from "../types";

// Generates an image using the Gemini API based on the provided settings.
export const generateImage = async (settings: GenerationSettings): Promise<{ imageUrl: string; text?: string }> => {
  // Always create a new GoogleGenAI instance right before the call to ensure the latest API key from the dialog is used.
  // The API key is obtained exclusively from process.env.API_KEY.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

  const config: any = {
    imageConfig: {
      aspectRatio: settings.aspectRatio,
    }
  };

  // Only gemini-3-pro-image-preview supports the imageSize configuration.
  if (settings.model === 'gemini-3-pro-image-preview') {
    config.imageConfig.imageSize = settings.imageSize;
  }

  // Use generateContent for nano banana series image models as per guidelines.
  const response = await ai.models.generateContent({
    model: settings.model,
    contents: {
      parts: [
        { text: settings.prompt }
      ],
    },
    config,
  });

  let imageUrl = "";
  let text = "";

  // The output response may contain both image and text parts; iterate through all parts to find the image part.
  const parts = response.candidates?.[0]?.content?.parts;
  if (parts) {
    for (const part of parts) {
      if (part.inlineData) {
        // Base64 encoded image data returned by the model.
        imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      } else if (part.text) {
        // Concatenate any accompanying text output.
        text += part.text;
      }
    }
  }

  if (!imageUrl) {
    throw new Error("No image data was returned by the model.");
  }

  return { imageUrl, text };
};

