                onChange={handleFileChange} 
                className="hidden" 
                accept="image/*" 
              />
            </div>
          ) : (
            <div className="relative aspect-video w-full rounded-xl overflow-hidden border border-zinc-700 bg-zinc-900 shadow-xl group">
              <img 
                src={`data:${settings.sourceImage.mimeType};base64,${settings.sourceImage.data}`} 
                className="w-full h-full object-cover" 
                alt="Source preview" 
              />
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                <button 
                  onClick={removeImage}
                  className="px-3 py-1.5 bg-red-500 text-white rounded-lg text-[10px] font-bold uppercase tracking-widest hover:bg-red-600 transition-colors shadow-lg"
