              </div>
            </div>
          )}
        </section>

        {/* Prompt Input */}
        <section className="space-y-3">
          <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">
            {settings.sourceImage ? 'Editing Instructions' : 'Image Prompt'}
          </label>
          <textarea
