            placeholder={settings.sourceImage ? "Describe the changes (e.g. 'Turn the sky purple', 'Add a cat')..." : "A futuristic city at night..."}
            className="w-full h-32 bg-zinc-900 border border-zinc-800 rounded-xl p-4 text-sm text-zinc-100 placeholder:text-zinc-600 focus:outline-none focus:ring-2 focus:ring-yellow-500/20 focus:border-yellow-500/50 resize-none transition-all"
          />
        </section>

        {/* Model Selection */}
        <section className="space-y-3">
