import React, { useState, useEffect, useCallback } from 'react';
import { 
  AspectRatio, 
  ImageSize, 
  ModelType, 
  GeneratedImage, 
  GenerationSettings 
} from './types';
import { generateImage } from './services/gemini';
import Sidebar from './components/Sidebar';
import Gallery from './components/Gallery';
import { Header } from './components/Header';

const App: React.FC = () => {
  const [images, setImages] = useState<GeneratedImage[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showKeyModal, setShowKeyModal] = useState(false);

  const [settings, setSettings] = useState<GenerationSettings>({
    prompt: '',
    aspectRatio: '1:1',
    imageSize: '1K',
    model: 'gemini-2.5-flash-image',
  });

  const handleGenerate = async () => {
    if (!settings.prompt.trim()) {
      setError("Please enter a prompt first.");
      return;
    }

    // Check for API key selection for Pro model
    if (settings.model === 'gemini-3-pro-image-preview') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        setShowKeyModal(true);
        return;
      }
    }

    setIsGenerating(true);
    setError(null);

    try {
      const result = await generateImage(settings);
      const newImage: GeneratedImage = {
        id: crypto.randomUUID(),
        url: result.imageUrl,
        prompt: settings.prompt,
        model: settings.model,
        timestamp: Date.now(),
        aspectRatio: settings.aspectRatio,
        textOutput: result.text,
      };
      setImages(prev => [newImage, ...prev]);
    } catch (err: any) {
      console.error(err);
      if (err.message?.includes("Requested entity was not found")) {
        setError("API Session expired or invalid. Please re-select your API key.");
        if (settings.model === 'gemini-3-pro-image-preview') {
          setShowKeyModal(true);
        }
      } else {
        setError(err.message || "An unexpected error occurred during generation.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeySelect = async () => {
    try {
      await window.aistudio.openSelectKey();
      setShowKeyModal(false);
      // Proceed immediately as per instructions
      handleGenerate();
    } catch (err) {
      console.error("Failed to select key", err);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#0a0a0a]">
      <Header />

      {/* Changed flex to flex-col md:flex-row to stack on mobile */}
      <main className="flex flex-col md:flex-row flex-1 overflow-hidden relative">
        <Sidebar 
          settings={settings} 
          setSettings={setSettings} 
          onGenerate={handleGenerate} 
          isGenerating={isGenerating}
        />

        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-zinc-950/50">
          {error && (
            <div className="mb-6 p-4 bg-red-500/10 border border-red-500/50 rounded-xl text-red-500 flex items-center gap-3">
              <span className="text-xl">⚠️</span>
              <p>{error}</p>
              <button 
                onClick={() => setError(null)}
                className="ml-auto text-red-400 hover:text-red-300"
              >
                ✕
              </button>
            </div>
          )}

          <Gallery images={images} isGenerating={isGenerating} />
        </div>
      </main>

      {/* API Key Modal */}
      {showKeyModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-3xl max-w-md w-full shadow-2xl">
            <h2 className="text-2xl font-bold mb-4 banana-text-gradient">API Key Required</h2>
            <p className="text-zinc-400 mb-6 leading-relaxed">
              To use the <span className="text-white font-medium">Gemini 3 Pro</span> high-quality model, you must select your own API key from a paid GCP project.
            </p>
            <div className="flex flex-col gap-4">
              <button
                onClick={handleKeySelect}
                className="w-full py-4 rounded-xl banana-gradient text-black font-bold text-lg hover:scale-[1.02] transition-transform active:scale-95"
              >
                Select API Key
              </button>
              <a 
                href="https://ai.google.dev/gemini-api/docs/billing" 
                target="_blank" 
                rel="noopener noreferrer"
                className="text-center text-zinc-500 text-sm hover:underline"
              >
                Learn about Gemini API billing
              </a>
              <button
                onClick={() => setShowKeyModal(false)}
                className="text-zinc-500 hover:text-white transition-colors py-2"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useCallback } from 'react';
import { GenerationSettings, AspectRatio, ImageSize, ModelType, SourceImage } from '../types';

interface SidebarProps {
  settings: GenerationSettings;
  setSettings: React.Dispatch<React.SetStateAction<GenerationSettings>>;
  onGenerate: () => void;
  isGenerating: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ settings, setSettings, onGenerate, isGenerating }) => {
  const aspectRatios: AspectRatio[] = ['1:1', '3:4', '4:3', '9:16', '16:9'];
  const sizes: ImageSize[] = ['1K', '2K', '4K'];
  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = useCallback((file: File) => {
    if (!file.type.startsWith('image/')) return;

    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      setSettings(s => ({
        ...s,
        sourceImage: {
          data: base64String,
          mimeType: file.type
        }
      }));
    };
    reader.readAsDataURL(file);
  }, [setSettings]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) processFile(file);
  };

  // Paste handler
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      const items = e.clipboardData?.items;
      if (!items) return;

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const file = items[i].getAsFile();
          if (file) {
            processFile(file);
            break;
          }
        }
      }
    };

    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [processFile]);

  const removeImage = () => {
    setSettings(s => ({ ...s, sourceImage: undefined }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    /* Changed classes to handle responsive sizing and borders */
    <aside className="w-full md:w-80 border-b md:border-b-0 md:border-r border-zinc-800 flex flex-col bg-[#0a0a0a] shrink-0 max-h-[50vh] md:max-h-full">
      <div className="flex-1 overflow-y-auto p-6 space-y-8">

        {/* Image Upload Section */}
        <section className="space-y-3">
          <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">
            Source Image (Optional)
          </label>
          {!settings.sourceImage ? (
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="w-full h-24 border-2 border-dashed border-zinc-800 hover:border-yellow-500/50 hover:bg-yellow-500/5 rounded-xl flex flex-col items-center justify-center cursor-pointer transition-all bg-zinc-900/30 group"
            >
              <span className="text-2xl group-hover:scale-110 transition-transform">📁</span>
              <span className="text-[10px] text-zinc-500 font-bold mt-2 tracking-tighter">UPLOAD OR PASTE TO EDIT</span>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                className="hidden" 
                accept="image/*" 
              />
            </div>
          ) : (
            <div className="relative aspect-video w-full rounded-xl overflow-hidden border border-zinc-700 bg-zinc-900 shadow-xl group">
              <img 
                src={`data:${settings.sourceImage.mimeType};base64,${settings.sourceImage.data}`} 
                className="w-full h-full object-cover" 
                alt="Source preview" 
              />
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                <button 
                  onClick={removeImage}
                  className="px-3 py-1.5 bg-red-500 text-white rounded-lg text-[10px] font-bold uppercase tracking-widest hover:bg-red-600 transition-colors shadow-lg"
                >
                  Remove Image
                </button>
              </div>
              <div className="absolute bottom-0 inset-x-0 bg-yellow-500/90 py-1 text-[8px] text-center font-black text-black uppercase">
                Image Locked For Edit
              </div>
            </div>
          )}
        </section>

        {/* Prompt Input */}
        <section className="space-y-3">
          <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">
            {settings.sourceImage ? 'Editing Instructions' : 'Image Prompt'}
          </label>
          <textarea
            value={settings.prompt}
            onChange={(e) => setSettings(s => ({ ...s, prompt: e.target.value }))}
            placeholder={settings.sourceImage ? "Describe the changes (e.g. 'Turn the sky purple', 'Add a cat')..." : "A futuristic city at night..."}
            className="w-full h-32 bg-zinc-900 border border-zinc-800 rounded-xl p-4 text-sm text-zinc-100 placeholder:text-zinc-600 focus:outline-none focus:ring-2 focus:ring-yellow-500/20 focus:border-yellow-500/50 resize-none transition-all"
          />
        </section>

        {/* Model Selection */}
        <section className="space-y-3">
          <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">Select Model</label>
          <div className="grid grid-cols-1 gap-2">
            <button
              onClick={() => setSettings(s => ({ ...s, model: 'gemini-2.5-flash-image' }))}
              className={`p-3 rounded-xl border text-left transition-all ${
                settings.model === 'gemini-2.5-flash-image' 
                ? 'bg-zinc-800 border-yellow-500/50 text-white shadow-[inset_0_0_20px_rgba(234,179,8,0.05)]' 
                : 'bg-zinc-900/50 border-zinc-800 text-zinc-500 hover:border-zinc-700'
              }`}
            >
              <div className="font-bold text-sm">Banana Flash</div>
              <div className="text-[10px] opacity-60">Fast & Watermark-Free</div>
            </button>
            <button
              onClick={() => setSettings(s => ({ ...s, model: 'gemini-3-pro-image-preview' }))}
              className={`p-3 rounded-xl border text-left transition-all relative overflow-hidden ${
                settings.model === 'gemini-3-pro-image-preview' 
                ? 'bg-zinc-800 border-yellow-500 text-white shadow-[inset_0_0_20px_rgba(234,179,8,0.1)]' 
                : 'bg-zinc-900/50 border-zinc-800 text-zinc-500 hover:border-zinc-700'
              }`}
            >
              <div className="font-bold text-sm flex items-center gap-2">
                Banana Pro <span className="px-1.5 py-0.5 rounded bg-yellow-500 text-[8px] text-black font-black uppercase">High Fidelity</span>
              </div>
              <div className="text-[10px] opacity-60">Requires Paid API Key</div>
            </button>
          </div>
        </section>

        {/* Aspect Ratio */}
        <section className="space-y-3">
          <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">Aspect Ratio</label>
          <div className="flex flex-wrap gap-2">
            {aspectRatios.map((ratio) => (
              <button
                key={ratio}
                onClick={() => setSettings(s => ({ ...s, aspectRatio: ratio }))}
                className={`flex-1 py-2 px-3 rounded-lg text-xs font-medium border transition-all ${
                  settings.aspectRatio === ratio 
                  ? 'bg-yellow-500 text-black border-yellow-500 shadow-lg shadow-yellow-500/20' 
                  : 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:border-zinc-700'
                }`}
              >
                {ratio}
              </button>
            ))}
          </div>
        </section>

        {/* Image Size (Only for Pro) */}
        {settings.model === 'gemini-3-pro-image-preview' && (
          <section className="space-y-3 animate-in fade-in slide-in-from-top-4 duration-300">
            <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">Resolution</label>
            <div className="grid grid-cols-3 gap-2">
              {sizes.map((size) => (
                <button
                  key={size}
                  onClick={() => setSettings(s => ({ ...s, imageSize: size }))}
                  className={`py-2 px-3 rounded-lg text-xs font-medium border transition-all ${
                    settings.imageSize === size 
                    ? 'bg-yellow-500 text-black border-yellow-500 shadow-lg shadow-yellow-500/20' 
                    : 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:border-zinc-700'
                  }`}
                >
                  {size}
                </button>
              ))}
            </div>
          </section>
        )}

      </div>

      {/* Persistent CTA */}
      <div className="p-6 border-t border-zinc-800 bg-[#0a0a0a]">
        <button
          onClick={onGenerate}
          disabled={isGenerating}
          className={`w-full py-4 rounded-xl font-bold flex items-center justify-center gap-3 transition-all ${
            isGenerating 
            ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed' 
            : 'banana-gradient text-black hover:scale-[1.02] active:scale-95 shadow-[0_10px_30px_rgba(234,179,8,0.2)]'
          }`}
        >
          {isGenerating ? (
            <>
              <div className="w-5 h-5 border-2 border-zinc-600 border-t-zinc-400 rounded-full animate-spin"></div>
              <span>{settings.sourceImage ? 'Modifying Image...' : 'Creating...'}</span>
            </>
          ) : (
            <>
              <span>{settings.sourceImage ? 'Transform Image' : 'Generate Image'}</span>
              <span className="text-xl leading-none">{settings.sourceImage ? '🪄' : '✨'}</span>
            </>
          )}
        </button>
      </div>
    </aside>
  );
};

