      {showKeyModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-3xl max-w-md w-full shadow-2xl">
            <h2 className="text-2xl font-bold mb-4 banana-text-gradient">API Key Required</h2>
            <p className="text-zinc-400 mb-6 leading-relaxed">
              To use the <span className="text-white font-medium">Gemini 3 Pro</span> high-quality model, you must select your own API key from a paid GCP project.
            </p>
            <div className="flex flex-col gap-4">
              <button
                onClick={handleKeySelect}
                className="w-full py-4 rounded-xl banana-gradient text-black font-bold text-lg hover:scale-[1.02] transition-transform active:scale-95"
              >
                Select API Key
              </button>
              <a 
                href="https://ai.google.dev/gemini-api/docs/billing" 
                target="_blank" 
                rel="noopener noreferrer"
                className="text-center text-zinc-500 text-sm hover:underline"
              >
                Learn about Gemini API billing
              </a>
              <button
                onClick={() => setShowKeyModal(false)}
                className="text-zinc-500 hover:text-white transition-colors py-2"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useCallback } from 'react';
import { GenerationSettings, AspectRatio, ImageSize, ModelType, SourceImage } from '../types';

interface SidebarProps {
  settings: GenerationSettings;
  setSettings: React.Dispatch<React.SetStateAction<GenerationSettings>>;
  onGenerate: () => void;
  isGenerating: boolean;
}

const MAX_IMAGES = 3;

const Sidebar: React.FC<SidebarProps> = ({ settings, setSettings, onGenerate, isGenerating }) => {
  const aspectRatios: AspectRatio[] = ['1:1', '3:4', '4:3', '9:16', '16:9'];
  const sizes: ImageSize[] = ['1K', '2K', '4K'];
  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFiles = useCallback((files: FileList | File[]) => {
    const remainingSlots = MAX_IMAGES - settings.sourceImages.length;
    if (remainingSlots <= 0) return;

    const filesToProcess = Array.from(files).slice(0, remainingSlots);

    filesToProcess.forEach(file => {
      if (!file.type.startsWith('image/')) return;

      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        setSettings(s => ({
          ...s,
          sourceImages: [...s.sourceImages, {
            data: base64String,
            mimeType: file.type
          }]
        }));
      };
      reader.readAsDataURL(file);
    });
  }, [settings.sourceImages.length, setSettings]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) processFiles(e.target.files);
    // Clear input so same file can be selected again if removed
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Paste handler
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      const items = e.clipboardData?.items;
      if (!items) return;

      const files: File[] = [];
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const file = items[i].getAsFile();
          if (file) files.push(file);
        }
      }
      if (files.length > 0) processFiles(files);
    };

    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [processFiles]);

  const removeImage = (index: number) => {
    setSettings(s => ({
      ...s,
      sourceImages: s.sourceImages.filter((_, i) => i !== index)
    }));
  };

  return (
    <aside className="w-full md:w-80 border-b md:border-b-0 md:border-r border-zinc-800 flex flex-col bg-[#0a0a0a] shrink-0 max-h-[50vh] md:max-h-full">
      <div className="flex-1 overflow-y-auto p-6 space-y-8">

        {/* Multi-Image Reference Section */}
        <section className="space-y-3">
          <div className="flex items-center justify-between">
            <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">
              References ({settings.sourceImages.length}/{MAX_IMAGES})
            </label>
            {settings.sourceImages.length > 0 && (
              <button 
                onClick={() => setSettings(s => ({ ...s, sourceImages: [] }))}
                className="text-[10px] text-zinc-600 hover:text-red-500 font-bold uppercase transition-colors"
              >
                Clear All
              </button>
            )}
          </div>

          <div className="grid grid-cols-3 gap-2">
            {settings.sourceImages.map((img, idx) => (
              <div key={idx} className="relative aspect-square rounded-lg overflow-hidden border border-zinc-700 bg-zinc-900 group">
                <img 
                  src={`data:${img.mimeType};base64,${img.data}`} 
                  className="w-full h-full object-cover" 
                  alt={`Ref ${idx + 1}`} 
                />
                <button 
                  onClick={() => removeImage(idx)}
                  className="absolute top-1 right-1 w-5 h-5 bg-black/60 hover:bg-red-500 rounded-full flex items-center justify-center text-[10px] opacity-0 group-hover:opacity-100 transition-all border border-white/10"
                >
                  ✕
                </button>
              </div>
            ))}

            {settings.sourceImages.length < MAX_IMAGES && (
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="aspect-square border-2 border-dashed border-zinc-800 hover:border-yellow-500/50 hover:bg-yellow-500/5 rounded-lg flex flex-col items-center justify-center cursor-pointer transition-all bg-zinc-900/30 group"
              >
                <span className="text-xl group-hover:scale-110 transition-transform opacity-40">➕</span>
                <span className="text-[8px] text-zinc-600 font-bold mt-1 tracking-tighter">ADD REF</span>
              </button>
            )}
          </div>

          <p className="text-[9px] text-zinc-600 italic">
            {settings.sourceImages.length > 0 
              ? "Models will remix these styles and characters." 
              : "Upload or paste images to use as visual context."}
          </p>

          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            className="hidden" 
            accept="image/*"
            multiple
          />
        </section>

        {/* Prompt Input */}
        <section className="space-y-3">
          <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">
            {settings.sourceImages.length > 0 ? 'Remix Prompt' : 'Image Prompt'}
          </label>
          <textarea
            value={settings.prompt}
            onChange={(e) => setSettings(s => ({ ...s, prompt: e.target.value }))}
            placeholder={settings.sourceImages.length > 0 
              ? "How should these be combined? (e.g. 'A portrait of character 1 in the style of image 2')..." 
              : "A futuristic city at night..."}
            className="w-full h-32 bg-zinc-900 border border-zinc-800 rounded-xl p-4 text-sm text-zinc-100 placeholder:text-zinc-600 focus:outline-none focus:ring-2 focus:ring-yellow-500/20 focus:border-yellow-500/50 resize-none transition-all"
          />
        </section>

        {/* Model Selection */}
        <section className="space-y-3">
          <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">Select Model</label>
          <div className="grid grid-cols-1 gap-2">
            <button
              onClick={() => setSettings(s => ({ ...s, model: 'gemini-2.5-flash-image' }))}
              className={`p-3 rounded-xl border text-left transition-all ${
                settings.model === 'gemini-2.5-flash-image' 
                ? 'bg-zinc-800 border-yellow-500/50 text-white shadow-[inset_0_0_20px_rgba(234,179,8,0.05)]' 
                : 'bg-zinc-900/50 border-zinc-800 text-zinc-500 hover:border-zinc-700'
              }`}
            >
              <div className="font-bold text-sm">Banana Flash</div>
              <div className="text-[10px] opacity-60">Fast & Watermark-Free</div>
            </button>
            <button
              onClick={() => setSettings(s => ({ ...s, model: 'gemini-3-pro-image-preview' }))}
              className={`p-3 rounded-xl border text-left transition-all relative overflow-hidden ${
                settings.model === 'gemini-3-pro-image-preview' 
                ? 'bg-zinc-800 border-yellow-500 text-white shadow-[inset_0_0_20px_rgba(234,179,8,0.1)]' 
                : 'bg-zinc-900/50 border-zinc-800 text-zinc-500 hover:border-zinc-700'
              }`}
            >
              <div className="font-bold text-sm flex items-center gap-2">
                Banana Pro <span className="px-1.5 py-0.5 rounded bg-yellow-500 text-[8px] text-black font-black uppercase">High Fidelity</span>
              </div>
              <div className="text-[10px] opacity-60">Requires Paid API Key</div>
            </button>
          </div>
        </section>

        {/* Aspect Ratio */}
        <section className="space-y-3">
          <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">Aspect Ratio</label>
          <div className="flex flex-wrap gap-2">
            {aspectRatios.map((ratio) => (
              <button
                key={ratio}
                onClick={() => setSettings(s => ({ ...s, aspectRatio: ratio }))}
                className={`flex-1 py-2 px-3 rounded-lg text-xs font-medium border transition-all ${
                  settings.aspectRatio === ratio 
                  ? 'bg-yellow-500 text-black border-yellow-500 shadow-lg shadow-yellow-500/20' 
                  : 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:border-zinc-700'
                }`}
              >
                {ratio}
              </button>
            ))}
          </div>
        </section>

        {/* Image Size (Only for Pro) */}
        {settings.model === 'gemini-3-pro-image-preview' && (
          <section className="space-y-3 animate-in fade-in slide-in-from-top-4 duration-300">
            <label className="text-xs font-bold text-zinc-400 uppercase tracking-widest">Resolution</label>
            <div className="grid grid-cols-3 gap-2">
              {sizes.map((size) => (
                <button
                  key={size}
                  onClick={() => setSettings(s => ({ ...s, imageSize: size }))}
                  className={`py-2 px-3 rounded-lg text-xs font-medium border transition-all ${
                    settings.imageSize === size 
                    ? 'bg-yellow-500 text-black border-yellow-500 shadow-lg shadow-yellow-500/20' 
                    : 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:border-zinc-700'
                  }`}
                >
                  {size}
                </button>
              ))}
            </div>
          </section>
        )}

      </div>

      {/* Persistent CTA */}
      <div className="p-6 border-t border-zinc-800 bg-[#0a0a0a]">
        <button
          onClick={onGenerate}
          disabled={isGenerating}
          className={`w-full py-4 rounded-xl font-bold flex items-center justify-center gap-3 transition-all ${
            isGenerating 
            ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed' 
            : 'banana-gradient text-black hover:scale-[1.02] active:scale-95 shadow-[0_10px_30px_rgba(234,179,8,0.2)]'
          }`}
        >
          {isGenerating ? (
            <>
              <div className="w-5 h-5 border-2 border-zinc-600 border-t-zinc-400 rounded-full animate-spin"></div>
              <span>{settings.sourceImages.length > 0 ? 'Remixing...' : 'Creating...'}</span>
            </>
          ) : (
            <>
              <span>{settings.sourceImages.length > 0 ? 'Remix Visuals' : 'Generate Image'}</span>
              <span className="text-xl leading-none">{settings.sourceImages.length > 0 ? '🪄' : '✨'}</span>
            </>
          )}
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;

export type AspectRatio = '1:1' | '3:4' | '4:3' | '9:16' | '16:9';
export type ImageSize = '1K' | '2K' | '4K';
export type ModelType = 'gemini-2.5-flash-image' | 'gemini-3-pro-image-preview';

export interface SourceImage {
  data: string; // base64 string
  mimeType: string;
}

export interface GeneratedImage {
  id: string;
  url: string;
  prompt: string;
  model: ModelType;
  timestamp: number;
  aspectRatio: AspectRatio;
  textOutput?: string;
}

export interface GenerationSettings {
  prompt: string;
  negativePrompt?: string;
  aspectRatio: AspectRatio;
  imageSize: ImageSize;
  model: ModelType;
  sourceImages: SourceImage[];
}

declare global {
  /**
   * The AIStudio interface defines the methods for managing API keys.
   * Declaring it inside the global block ensures it correctly matches and merges
   * with the expected global type in the execution environment.
   */
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    /**
     * The aistudio property is used for managing API keys in specific model contexts.
     * We remove the 'readonly' modifier to ensure this declaration is identical 
     * to the one already present in the global scope, avoiding modifier mismatch errors.
     */
    // Fix: Removed 'readonly' modifier to match other existing declarations of 'aistudio'.
    aistudio: AIStudio;
  }
}
